import json, sys
from playwright.sync_api import sync_playwright
fx = json.load(open('/tmp/fixtures_v38.json')); gid = fx['gid']
errors = []; passed = 0; failed = 0
SHOTS = sys.argv[1] if len(sys.argv) > 1 else None
def ok(c, msg):
    global passed, failed
    if c: passed += 1; print('  ✓', msg)
    else: failed += 1; print('  ✗ FAIL:', msg)
def emit(page, ev, data): page.evaluate("([e,d]) => window.__srv.emit(e,d)", [ev, data])
def sent(page, name): return page.evaluate("(n) => (window.__sent||[]).filter(x => x[0]===n).map(x => x[1])", name)
def clear(page): page.evaluate("() => { window.__sent = []; }")
def shot(page, name):
    if SHOTS: page.screenshot(path=f'{SHOTS}/{name}.png')
def route_block(page):
    for pat in ('**/cdnjs.cloudflare.com/**', '**/flagcdn.com/**', '**/fonts.googleapis.com/**', '**/fonts.gstatic.com/**'): page.route(pat, lambda r: r.abort())
def watch(page, tag):
    page.on('pageerror', lambda e: errors.append(tag + ' PAGEERROR ' + str(e)))
    page.on('response', lambda r: errors.append(tag + ' HTTP404 ' + r.url) if r.status == 404 else None)
def box(page, sel): return page.evaluate("(s) => { const r = document.querySelector(s).getBoundingClientRect(); return {x: r.x, y: r.y, w: r.width, h: r.height, r: r.right, b: r.bottom} }", sel)

with sync_playwright() as p:
    b = p.chromium.launch()
    ctx = b.new_context(viewport={'width': 390, 'height': 740}); ctx.add_init_script("sessionStorage.setItem('q_splash_done','1'); localStorage.setItem('q_intro_done','1')")
    page = ctx.new_page(); watch(page, 'SELLER'); route_block(page)
    page.goto(f'http://localhost:8099/?groupId={gid}&role=SELLER', wait_until='load'); page.wait_for_timeout(600)
    ver = {**fx['verified'], 'countryIso': 'GH'}
    emit(page, 'init-state', fx['init']); emit(page, 'seller-account-state', ver); page.wait_for_timeout(300)
    page.evaluate("() => { const o = document.getElementById('onboardingOverlay'); if (o) o.remove(); }")

    print('\nA. Seller chat header and chat-room access (phone)')
    ok(not page.is_visible('#notifyToggleBtn') and not page.is_visible('#emailAlertsBtn'), 'the bell and the envelope are gone from the seller chat header')
    page.evaluate("() => openTxAccountView()"); page.wait_for_timeout(300)
    ok(page.locator('#txSupportBtn').count() == 0 and page.locator('#txBellBtn').count() == 0, 'Support and the bell are gone from the dashboard top bar')
    ok(page.is_visible('#txFlagChip') and page.locator('#txFlagChip img.flag').count() == 1 and page.get_attribute('#txFlagChip', 'title') == 'Ghana', 'the seller\'s country flag shows at the right of the top bar')
    ok(page.is_visible('#txChatPill'), 'a "Chat room" button sits beside the profile icon')
    cp, av = box(page, '#txChatPill'), box(page, '#txAvatar')
    ok(cp['x'] > av['x'] and abs((cp['y'] + cp['h'] / 2) - (av['y'] + av['h'] / 2)) < 14, 'v3.13: it sits in the top bar on the same row as the profile icon')
    shot(page, 'v40_topbar_phone')
    page.click('#txChatPill'); page.wait_for_timeout(150)
    ok(not page.is_visible('#txAccountView'), 'tapping it opens the chat room')
    page.evaluate("() => openTxAccountView()"); page.wait_for_timeout(200)
    labels = page.evaluate("() => [...document.querySelectorAll('#txBottomNav button')].map(b => b.textContent.trim())")
    ok(labels == ['Home', 'Transfer', 'Cards', 'Activity', 'Profile'], 'v3.13 bottom bar: ' + str(labels))
    page.evaluate("() => toggleTxSidebar()"); page.wait_for_timeout(400)
    ok(page.is_visible('#txNavChat'), 'the sidebar starts with a clear "Chat room" button')
    back = page.locator('.tx-sidebar .v41-sidefoot .tx-back-chat'); ok('Back to chat room' in back.inner_text(), 'the old "Back to chat" is now "Back to chat room"')
    bb = box(page, '.tx-sidebar .v41-sidefoot .tx-back-chat')
