    ok(top and bb['b'] <= 740, 'it is no longer hidden under the bottom bar (the tap point lands on it)')
    shot(page, 'v40_sidebar_phone')
    names = page.evaluate("() => [...document.querySelectorAll('.tx-nav [data-txnav]')].map(b => b.dataset.txnav)")
    ok('notifications' in names and names.index('notifications') > names.index('security') and names.index('notifications') < names.index('profile'), 'Notifications is in the list, after Security and before Profile: ' + ','.join(names))
    page.evaluate("() => setTxAccountNav('dashboard')")

    print('\nB. Notifications page')
    emit(page, 'seller-notice', {'kind': 'tracking', 'title': 'Payment update', 'body': 'IN-1001: Stage 2 is now in review'}); page.wait_for_timeout(150)
    ok(not page.locator('#v40NavDot').evaluate("e => e.classList.contains('hidden')"), 'a new update puts a red dot on Notifications')
    page.evaluate("() => setTxAccountNav('notifications')"); page.wait_for_timeout(200)
    t = page.inner_text('#txNotificationsBody')
    ok('Payment update' in t and 'Stage 2' in t and page.locator('#v40NavDot.hidden').count() == 1, 'the update is listed and the dot clears when opened')
    ok('Turn on' in t or 'on for this device' in t or 'cannot show' in t, 'the page shows the push-notification status / a one-tap button')
    ok(page.inner_text('#txPageTitle') == 'Notifications', 'page title is Notifications')
    shot(page, 'v40_notifications')

    print('\nC. Accounts: name automatic, numbers hidden until the eye is tapped')
    emit(page, 'receiving-details', fx['detailsUSD']); page.evaluate("() => setTxAccountNav('accounts')"); page.wait_for_timeout(250)
    t = page.inner_text('#txAccountsBody'); usd = dict((r[0], r[1]) for r in fx['detailsUSD']['details']['USD']['a'] + fx['detailsUSD']['details']['USD']['b'])
    ok(usd['Account number'] not in t and usd['ABA routing number'] not in t and '•' in t, 'account number and routing number show as ••••')
    ok(usd['Account name'] in t and usd['SWIFT / BIC'] in t and usd['Bank name'] in t, 'the account name, SWIFT and bank are visible')
