    page.click('#rcNumEye'); page.wait_for_timeout(100); t = page.inner_text('#txAccountsBody')
    ok(usd['Account number'] in t and usd['ABA routing number'] in t, 'tapping the eye shows everything')
    page.click('#rcNumEye'); page.evaluate("() => setTxAccountNav('dashboard'); setTxAccountNav('accounts')"); page.wait_for_timeout(150)
    ok(usd['Account number'] not in page.inner_text('#txAccountsBody'), 'leaving and returning hides them again')
    shot(page, 'v40_accounts_shown')

    print('\nD. Chat box (phone, 360px)')
    page.evaluate("() => closeTxAccountView()"); page.set_viewport_size({'width': 360, 'height': 700}); page.wait_for_timeout(200)
    page.fill('#messageInput', 'Hello, this is a long message to check that typing is comfortable on a narrow phone screen and wraps normally.'); page.wait_for_timeout(150)
    ta, mic, snd = box(page, '#messageInput'), box(page, '#micBtn'), box(page, '.send-btn-elite')
