    ok(page.locator('#pasteBtn').count() == 0 or not page.is_visible('#pasteBtn'), 'the clipboard button is gone')
    tools = page.evaluate("() => [...document.querySelectorAll('#composerTools > *')].map(e => e.id)")
    ok(tools == ['moreOptionsBtn', 'translateToggleBtn', 'fileUploadLabel'], 'options, translate and attach stay together on their own row: ' + str(tools))
