    shot(page, 'v40_composer_desktop')

    print('\nE. Universal keyboard settings on fields')
    page.evaluate("() => { document.body.insertAdjacentHTML('beforeend', '<input id=\"t_email\" type=\"email\"><input id=\"t_name\" id2=\"x\"><input id=\"txRegNameInput\"><input id=\"t_pw\" type=\"password\"><input id=\"t_tel\" type=\"tel\">'); }"); page.wait_for_timeout(100)
    g = lambda i: page.evaluate("(i) => { const e = document.getElementById(i); return [e.getAttribute('autocapitalize'), e.getAttribute('autocorrect'), e.getAttribute('spellcheck'), e.getAttribute('inputmode')] }", i)
    ok(g('t_email') == ['none', 'off', 'false', 'email'], 'email fields: lower-case, no auto-correct, email keyboard (also on fields added later)')
    ok(g('txRegNameInput')[0] == 'words' and g('txRegNameInput')[1] == 'on', 'name fields: Capitalised Words + auto-correct')
    ok(g('t_pw')[1] == 'off' and g('t_tel')[3] == 'tel', 'password: no auto-correct; phone: number pad')

    page.evaluate("() => ['t_email','t_name','txRegNameInput','t_pw','t_tel'].forEach(i => { const e = document.getElementById(i); if (e && i !== 'txRegNameInput') e.remove(); })")
    print('\nF. Registration phone must match the country')
    page.evaluate("() => { document.body.insertAdjacentHTML('beforeend','<div></div>'); }")
    page.evaluate("() => { pickState.mode = 'country'; pickCountry('GH'); }")
    ok(page.evaluate("() => pickState.dial.iso") == 'GH' and page.inner_text('#txRegDialText') == '+233', 'choosing Ghana sets the phone code to +233 automatically')
    page.evaluate("() => { pickState.mode = 'dial'; pickCountry('NG'); }")
    page.evaluate("(v) => { document.getElementById('txRegPhoneInput').value = v; }", '0244123456'); page.evaluate("() => v40RegPhoneHint(true)")
    h = (page.text_content('#txRegPhoneHint') or ''); ok('belongs to Nigeria' in h and 'Ghana' in h, 'a Nigerian code with Ghana selected is explained: ' + h.strip())
    page.evaluate("() => { pickState.mode = 'dial'; pickCountry('GH'); }")
    page.evaluate("(v) => { document.getElementById('txRegPhoneInput').value = v; }", '024412'); page.evaluate("() => v40RegPhoneHint(true)")
    ok('9 digits' in (page.text_content('#txRegPhoneHint') or ''), 'a short number is explained: ' + (page.text_content('#txRegPhoneHint') or '').strip())
    page.evaluate("(v) => { document.getElementById('txRegPhoneInput').value = v; }", '0244 123 456'); page.dispatch_event('#txRegPhoneInput', 'input')
    ok('+233244123456' in (page.text_content('#txRegPhoneHint') or '') and page.locator('#txRegPhoneHint.good').count() == 1, 'a correct number gets a green tick with the full number')
    shot(page, 'v40_phone_hint')

    print('\nG. Desk: Add seller, silent email change, card billing')
    ap = ctx.new_page(); watch(ap, 'ADMIN'); route_block(ap)
    ap.on('dialog', lambda d: d.accept())
    ap.goto(f'http://localhost:8099/?officer=1&groupId={gid}', wait_until='load'); ap.wait_for_timeout(500); ap.evaluate("() => v41OfficerClose()")
    ap.evaluate("() => { document.body.classList.add('is-admin','role-super_admin'); }"); ap.wait_for_timeout(100)
    ok(ap.is_visible('#notifyToggleBtn') and ap.is_visible('#emailAlertsBtn'), 'the Desk keeps the bell and envelope in the chat header')
    ap.evaluate("() => openAddSeller()"); ap.wait_for_timeout(300)
    ok(ap.is_visible('#asCountryBtn') and not ap.is_visible('#asCountry'), 'Add seller: the white native country list is replaced by a button')
    ap.click('#asCountryBtn'); ap.wait_for_timeout(250)
    zi = ap.evaluate("() => [+getComputedStyle(document.getElementById('countryPickerModal')).zIndex, +getComputedStyle(document.getElementById('addSellerModal')).zIndex]")
    ok(ap.is_visible('#countryPickerModal') and zi[0] > zi[1], 'the country list opens above the form')
    bg = ap.evaluate("() => { const c = getComputedStyle(document.querySelector('#countryPickerModal .modal-box')).backgroundColor.match(/\\d+/g).map(Number); return c }")
    ok(sum(bg[:3]) < 200, 'the list has a dark background, not white: rgb(' + ','.join(map(str, bg[:3])) + ')')
    sc = ap.evaluate("() => { const l = document.getElementById('countryList'); l.scrollTop = 0; const h = l.scrollHeight - l.clientHeight; l.scrollTop = 400; return [h, l.scrollTop, getComputedStyle(l).overflowY] }")
    ok(sc[0] > 500 and sc[1] > 0 and sc[2] in ('auto', 'scroll'), f'the list scrolls ({sc[0]}px of hidden options)')
    shot(ap, 'v40_add_seller_picker')
    ap.fill('#countrySearch', 'nige'); ap.wait_for_timeout(100); ap.click('#countryList .picker-item:has-text("Nigeria")'); ap.wait_for_timeout(150)
    ok(ap.input_value('#asCountry', timeout=1000) == 'NG' and 'Nigeria' in ap.inner_text('#asCountryBtn'), 'picking Nigeria fills the form (value NG)')
    ok(ap.locator('#addSellerModal .csel-trigger').count() >= 2, 'currency and language use the dark dropdown too')
    ap.fill('#asPhone', '123'); ap.evaluate("() => v40AsPhoneHint(true)")
    ok('Nigeria phone numbers' in ap.inner_text('#asPhoneHint'), 'a wrong-length number is flagged under the field')
    ap.fill('#asName', 'Ngozi Eze'); ap.fill('#asEmail', 'ngozi@example.com'); clear(ap); ap.click('#asBtn'); ap.wait_for_timeout(100)
    ok(len(sent(ap, 'admin-add-seller')) == 0, 'the form refuses to send a wrong phone number')
    ap.fill('#asPhone', '0803 123 4567'); ap.click('#asBtn'); a = sent(ap, 'admin-add-seller')
    ok(len(a) == 1 and a[0]['country'] == 'NG' and a[0]['email'] == 'ngozi@example.com', 'a valid number goes through')
    ap.evaluate("() => { closeModal('addSellerModal'); openModal('sellerProfileModal'); document.getElementById('spBody').innerHTML = '<p>profile</p>'; }")
    acct = {**fx['adminProfile']['account'], 'emailChanges': [{'at': '2026-10-20T10:00:00Z', 'from': 'old@example.com', 'to': 's1@example.com', 'silent': True}]}
    emit(ap, 'seller-profile', {'groupId': gid, 'account': acct, 'viewer': fx['adminProfile'].get('viewer')}); ap.wait_for_timeout(300)
    ok(ap.is_visible('#spEmailChange') and 'Nothing is sent' in ap.inner_text('#spEmailChange') and 'old@example.com' in ap.inner_text('#spEmailChange'), 'the seller profile has "Change email address" with the history and a clear "nothing is sent" note')
    clear(ap); ap.fill('#spNewEmail', 'bad'); ap.click('#spEmailChange .send-btn'); ap.wait_for_timeout(100)
    ok(len(sent(ap, 'admin-change-seller-email')) == 0, 'an invalid address is not sent')
    ap.fill('#spNewEmail', 'Kwame.New@example.com'); ap.click('#spEmailChange .send-btn'); a = sent(ap, 'admin-change-seller-email')
    ok(len(a) == 1 and a[0]['groupId'] == gid and a[0]['email'] == 'kwame.new@example.com', 'a valid new address is sent (after the confirmation)')
    shot(ap, 'v40_admin_email')
    ap.evaluate("() => { document.body.classList.add('is-admin','role-super_admin'); openAdminDrawerTab('controls'); }"); ap.wait_for_timeout(200)
    emit(ap, 'card-queue', {'list': [{'groupId': gid, 'sellerName': 'Kwame Mensah', 'accountId': '48291037561', 'status': 'processing', 'fee': {'paid': True, 'amount': 20, 'currency': 'USD', 'ref': 'CF-AB12CD34'}, 'appliedAt': '2026-10-22T10:00:00Z', 'billingText': '350 Fifth Avenue, Suite 4, New York, NY 10118, United States'}], 'eligible': [], 'fee': 20}); ap.wait_for_timeout(200)
    ok('350 Fifth Avenue' in ap.inner_text('#cardsBox .v40-adminbill') and ap.locator('#cardsBox [data-ci$=".pan"]').count() == 1, 'the Desk sees the card\'s billing address right above the issue form')
    shot(ap, 'v40_admin_card_billing')

    print('\nH. Card page: billing form on a phone')
