    emit(page, 'my-card', {'eligible': True, 'program': 'AIRWX', 'network': 'Visa', 'status': 'none', 'fee': {'usd': 20, 'amount': 20, 'currency': 'USD', 'paid': False}, 'balance': {'available': 100, 'enough': True, 'short': 0}, 'verified': True, 'holder': 'Kwame Mensah', 'billingDefaultIso': 'GH'}); page.wait_for_timeout(250)
    ok(page.is_visible('#v40BillForm') and 'Ghana' in page.inner_text('#cbCountryBtn'), 'the billing form opens with the seller\'s own country already chosen (Ghana)')
    ok(page.evaluate("() => document.documentElement.scrollWidth <= innerWidth"), 'no sideways scroll on the card page')
    shot(page, 'v40_card_billing_phone')
    emit(page, 'my-card', {'eligible': True, 'program': 'AIRWX', 'network': 'Visa', 'status': 'awaiting_fee', 'fee': {'usd': 20, 'amount': 20, 'currency': 'USD', 'paid': False}, 'balance': {'available': 100, 'enough': True, 'short': 0}, 'verified': True, 'holder': 'Kwame Mensah', 'billing': {'address1': '5 Ring Road', 'address2': '', 'city': 'Accra', 'state': 'Greater Accra', 'zip': '', 'country': 'Ghana', 'countryIso': 'GH'}}); page.wait_for_timeout(250)
    ok('5 Ring Road, Accra' in page.inner_text('#txCardBody') and page.locator('.v40-editbill').count() == 1, 'after applying, the address is shown with an "Edit billing address" option')

    print('\nI. Closed trading room: the app opens, never a dead end')
    p2 = ctx.new_page(); watch(p2, 'CLOSED'); route_block(p2)
    p2.goto(f'http://localhost:8099/?groupId={gid}&role=SELLER', wait_until='load'); p2.wait_for_timeout(600)
    ok('expired' not in (p2.title() or '').lower() and p2.locator('#messageInput').count() == 1, 'the page is the app itself (HTTP 200), not an "expired" page')
    emit(p2, 'room-closed', {'reason': 'revoked', 'hasAccount': True, 'needLogin': True}); p2.wait_for_timeout(500)
