    ok(p2.locator('#gateClosedNote').count() == 0 and 'no longer opens' not in p2.inner_text('#appGate') and 'expired' not in p2.inner_text('#appGate').lower(), 'v3.13: NO notice box at all - just the welcome, Sign in and Create account')
    ok(p2.is_visible('#gvWelcome button:has-text("Sign in")') and p2.is_visible('#gvWelcome button:has-text("Create account")'), 'Sign in and Create account are both offered')
    shot(p2, 'v40_closed_gate_phone')
    p3 = ctx.new_page(); watch(p3, 'CLOSED2'); route_block(p3)
    p3.goto(f'http://localhost:8099/?groupId={gid}&role=SELLER', wait_until='load'); p3.wait_for_timeout(600)
    emit(p3, 'seller-account-state', ver); emit(p3, 'init-state', {**fx['init'], 'roomClosed': True, 'closedReason': 'removed', 'messages': []}); p3.wait_for_timeout(900)
    p3.evaluate("() => { const o = document.getElementById('onboardingOverlay'); if (o) o.remove(); }")
    ok(p3.is_visible('#txAccountView') and p3.locator('#roomClosedBox').count() == 1, 'a signed-in person whose room closed lands on THEIR ACCOUNT (the room shows "closed")')
    ok(p3.is_visible('#v40ClosedBanner') and not p3.is_visible('#txChatPill') and not p3.is_visible('#txNavChat') and not p3.is_visible('#txBottomNav [data-bn-chat]'), 'a banner explains it, and every "Chat room" button is hidden')
